import { useState } from "react";

export function Drawer({
  title = "{{title}}",
  side = "{{side}}",
  width = {{width}},
  accent = "{{accent}}",
  backdrop = {{backdrop}},
  open: initialOpen = {{open}},
}) {
  const [open, setOpen] = useState(initialOpen);
  const positions = {
    left: { left: 0, top: 0, bottom: 0, width, borderRight: `4px solid ${accent}`, transform: open ? "translateX(0)" : "translateX(-100%)" },
    right: { right: 0, top: 0, bottom: 0, width, borderLeft: `4px solid ${accent}`, transform: open ? "translateX(0)" : "translateX(100%)" },
    top: { top: 0, left: 0, right: 0, height: width, borderBottom: `4px solid ${accent}`, transform: open ? "translateY(0)" : "translateY(-100%)" },
    bottom: { bottom: 0, left: 0, right: 0, height: width, borderTop: `4px solid ${accent}`, transform: open ? "translateY(0)" : "translateY(100%)" },
  };
  return (
    <div style={{ position: "relative", minHeight: 360, borderRadius: 12, overflow: "hidden",
      background: backdrop ? "rgba(36,20,48,.45)" : "#FAF7F2" }}>
      {!open && (
        <button type="button" onClick={() => setOpen(true)} style={{ position: "absolute", top: 16, left: 16,
          padding: "8px 14px", borderRadius: 8, border: "1.5px solid #24143033", background: "#FAF7F2", cursor: "pointer" }}>
          Open drawer
        </button>
      )}
      <div role="dialog" aria-modal={backdrop ? "true" : "false"} aria-labelledby="drawer-title" style={{
        position: "absolute", boxSizing: "border-box", background: "#FAF7F2", color: "#241430", padding: 20,
        boxShadow: "0 20px 44px rgba(36,20,48,.28)", transition: "transform .2s ease", fontFamily: "system-ui, sans-serif",
        ...positions[side] }}>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 10 }}>
          <h3 id="drawer-title" style={{ margin: 0, fontSize: 17, fontWeight: 600 }}>{title}</h3>
          <button type="button" onClick={() => setOpen(false)} aria-label="Close" style={{
            background: "none", border: "none", cursor: "pointer", color: "#241430", padding: 4, borderRadius: 6 }}>
            <svg width="14" height="14" viewBox="0 0 14 14" aria-hidden="true"><path d="M1 1l12 12M13 1L1 13" stroke="currentColor" strokeWidth="1.6" fill="none" strokeLinecap="round"/></svg>
          </button>
        </div>
        <p style={{ margin: 0, fontSize: 14, color: "#241430cc" }}>Panel content lives here, for filters, forms, or navigation that do not need a full page.</p>
      </div>
    </div>
  );
}
